-- scripts/research/factory-i2-independent/independent.sql
select jsonb_build_object(
  'measuredAt', now(),
  'applications', (select jsonb_agg(jsonb_build_object('surface_ref', surface_ref, 'item_id', item_id, 'status', status, 'version', version, 'audience', audience, 'release_approved', release_approved_at is not null) order by surface_ref) from knowledge_applications where surface='csat_item_task' and (surface_ref like 'claim-support:%' or surface_ref='option-restate:2026-23')),
  'graph', jsonb_build_object('items', (select jsonb_agg(jsonb_build_object('id', id, 'slug', slug, 'title', title, 'layer', layer, 'kind', kind, 'status', status, 'version', version, 'efficacy', efficacy) order by slug) from knowledge_items), 'links', (select jsonb_agg(jsonb_build_object('from_id', from_id, 'to_id', to_id, 'kind', kind) order by from_id,to_id) from knowledge_links where kind='implements')),
  'phaseActivity', (select jsonb_agg(to_jsonb(g)) from (select task_key, phase, activity, synthetic, count(*) as attempts from learning_task_attempts where item_ref in (select audience->>'item' from knowledge_applications where surface_ref like 'claim-support:%') group by task_key,phase,activity,synthetic order by task_key,phase,activity,synthetic) g),
  'normalizedShared', (select jsonb_agg(jsonb_build_object('item',p.id,'otherItems',(select coalesce(jsonb_agg(q.id order by q.id),'[]'::jsonb) from csat_items q where q.id<>p.id and q.passage is not null and regexp_replace(lower(q.passage),'\s+',' ','g')=regexp_replace(lower(p.passage),'\s+',' ','g'))) order by p.id) from csat_items p where p.id in (select audience->>'item' from knowledge_applications where surface_ref like 'claim-support:%')),
  'publicBodies', (select jsonb_build_object('ids',jsonb_agg(i.id order by i.id),'items',count(*),'public',count(*) filter(where exists(select 1 from csat_items_public p where p.id=i.id)), 'published',count(*) filter(where exists(select 1 from csat_item_analyses a where a.item_id=i.id and a.status='published')), 'bodyOk',count(*) filter(where i.body_ok)) from csat_items i join csat_exams e on e.id=i.exam_id where e.organizer='kice' and i.type_id in ('R-CLAIM','R-GIST','R-TOPIC','R-TITLE') and i.id not in ('2014A#24','2014B#23')),
  'session2026_23', (select jsonb_build_object('sessions',count(*),'explanations',count(explanation_viewed_at),'reveals',count(revealed_at),'deleted',count(deleted_at),'synthetic',count(*) filter(where synthetic)) from learning_sessions where item_ref='2026#23'),
  'g2Columns', (select jsonb_object_agg(table_name,cols) from (select table_name,jsonb_agg(column_name order by ordinal_position) cols from information_schema.columns where table_schema='public' and table_name in ('learning_task_attempts','learning_sessions') group by table_name) g),
  'otherExposureColumns', (select jsonb_object_agg(table_name,cols) from (select table_name,jsonb_agg(column_name order by ordinal_position) cols from information_schema.columns where table_schema='public' and table_name in ('csat_trap_attempts','csat_session_attempts','csat_review_queue') group by table_name) g),
  'gateFunctions',(select jsonb_agg(jsonb_build_object('name',proname,'args',pg_get_function_arguments(oid),'body',prosrc) order by proname) from pg_proc where pronamespace='public'::regnamespace and proname in ('csat_ec_embargoed_items','csat_ec_embargoed_exams'))
) as audit;
